#include "ksStateProgramLoadForeground.h"
#include "ksControllerState.h"
namespace ks {namespace {
int history(uint32_t a){a&=0xffffff;return a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;}
bool endpoint(uint32_t a){return StateProgramLoadService::readSpan(a,1)||(a>=0x1c0&&a<0x300)||(a>=0x400000&&a<0x400010)||(a>=0x600000&&a<0x600010)||a==0xffff51||a==0xffff61||a==0xffff62||a==0xfffeb1||a==0xffff8a;}
struct Resolver{bool operator()(uint8_t c,uint32_t p)const{switch(c){case 0:return p==0x4f4a;case 2:return p==0x51d8;case 3:return p==0x51f4;case 4:return p==0x5252;case 6:return p==0x51fe;default:return false;}}};
}
bool StateProgramLoadForeground::step(ControllerCpu&h){using T=StateProgramLoadService;if(!job_){if(!h.nativeFetchClocksOnly||!h.nativeLowBase||h.nativeLowSize<0x18a00||!h.interruptMode2||h.indent<=0)return false;T::Kind k;switch(h.getPC()){case 0x62e6:k=T::Kind::CommitSingle;break;case 0x633a:k=T::Kind::CommitMulti;break;case 0x6382:k=T::Kind::LoadSingle;break;default:return false;}const auto sp=h.getSP();if((sp&1)||sp<0xfff400||sp>0xfffbfc)return false;const auto peek=[&](uint32_t raw){const auto a=raw&0xffffff;return a<h.nativeLowSize?h.nativeLowBase[a]:h.memory[a];};if(!T::admitted(k,peek,Resolver{}))return false;job_.emplace(k,T::Input{uint16_t(h.regs[6].r)},sp,h.indent,h.exr);++started;++kinds[unsigned(k)];}
 auto&j=*job_;if(j.depth!=h.indent)return false;auto&s=j.service;const auto cost=s.nextClocks(h.lastwrite);const auto start=h.cycles;const auto previous=h.lastwrite;const auto used=s.advanceBefore(cost,[&](uint32_t raw,unsigned dt){const auto a=raw&0xffffff;if(!endpoint(a))throw std::logic_error("Unsupported evolving program read endpoint");h.cycles=start+dt;h.lastread=history(a);return h.readResource(a);},[&](uint32_t raw,uint8_t v,unsigned dt){const auto a=raw&0xffffff;if(!endpoint(a))throw std::logic_error("Unsupported evolving program write endpoint");h.cycles=start+dt;h.lastwrite=history(a);h.writeResource(a,v);},Resolver{},previous);if(!cost||used!=cost)throw std::logic_error("Program phase admission differs");if(s.effect().read)h.lastread=-1;if(s.effect().write)h.lastwrite=-1;h.exr=s.critical()?7:j.priority;++phases;components|=s.components();
 if(s.complete()){CallerAbi a;for(unsigned n=0;n<7;++n)a.values[n]=uint32_t(h.regs[n].er);a.flags=h.ccr;project(a,s);for(unsigned n=0;n<7;++n)h.regs[n].er=int32_t(a.values[n]);h.ccr=a.flags;h.exr=j.priority;uint32_t target=0;for(unsigned n=0;n<4;++n){h.cycles=start+8+3*n;h.lastread=-1;target=(target<<8)|h.readResource(j.caller+n);}h.setSP(j.caller+4);h.pc=target&0xffffff;--h.indent;job_.reset();++completed;}h.cycles=start+cost;return true;}
}
